/** Array manipulation utilities. */
/** Removes duplicate elements from an array. */
export declare const unique: <T>(arr?: T[]) => T[];
/** Sorts an array and returns a new sorted array. */
export declare const sort: <T>(arr?: T[], sorting?: ((a: T, b: T) => number) | null) => T[];
/** Sorts an array of objects by a specified property. */
export declare const sortBy: <T extends Record<string, any>>(arr?: T[], order?: number, key?: string) => T[];
/** Randomly shuffles array elements using Fisher-Yates algorithm. */
export declare const shuffle: <T>(arr?: T[]) => T[];
/** Randomly picks N elements from an array. */
export declare const pick: <T>(arr?: T[], count?: number) => T[];
/** Splits an array into chunks of specified size. */
export declare const chunk: <T>(arr?: T[], size?: number) => T[][];
/** Flattens a nested array to specified depth. */
export declare const flatten: <T>(arr?: any[], depth?: number) => T[];
/** Groups array elements by a specified key or function. */
export declare const groupBy: <T>(arr: T[] | undefined, key: string | ((item: T) => string)) => Record<string, T[]>;
/** Gets the first n elements of an array. */
export declare const first: <T>(arr?: T[], n?: number) => T[];
/** Gets the last n elements of an array. */
export declare const last: <T>(arr?: T[], n?: number) => T[];
/** Removes all falsy values from an array. */
export declare const compact: <T>(arr?: T[]) => T[];
/** Gets elements in arr1 but not in arr2. */
export declare const difference: <T>(arr1?: T[], arr2?: T[]) => T[];
/** Gets elements present in both arrays. */
export declare const intersection: <T>(arr1?: T[], arr2?: T[]) => T[];
/** Combines two arrays into pairs. */
export declare const zip: <T, U>(arr1?: T[], arr2?: U[]) => [T, U][];
